---
interface FeatureItem {
  title: string
  description: string
}

export interface Props {
  heading?: string
  items?: FeatureItem[]
}

const {
  heading = "Built for expressive interfaces",
  items = [
    {
      title: "Editorial layouts",
      description: "Compose dense sections without the brittle wrapper soup.",
    },
    {
      title: "Motion-ready surfaces",
      description: "Cards, ribbons, and panels designed to take animation well.",
    },
    {
      title: "Astro-first output",
      description: "Ship components as .astro files without pulling React in.",
    },
  ],
} = Astro.props
---

<section class="feature-grid">
  <div class="feature-grid-header">
    <span>Toolkit</span>
    <h2>{heading}</h2>
  </div>

  <div class="feature-grid-items">
    {
      items.map((item, index) => (
        <article class="feature-grid-item" style={`--item-index:${index};`}>
          <strong>{item.title}</strong>
          <p>{item.description}</p>
        </article>
      ))
    }
  </div>
</section>

<style>
  .feature-grid {
    display: grid;
    gap: 1.5rem;
  }

  .feature-grid-header {
    display: grid;
    gap: 0.5rem;
  }

  .feature-grid-header span {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgb(249 115 22);
  }

  .feature-grid-header h2 {
    margin: 0;
    font-size: clamp(1.75rem, 4vw, 3rem);
    line-height: 1;
    color: rgb(15 23 42);
    text-wrap: balance;
  }

  .feature-grid-items {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
    gap: 1rem;
  }

  .feature-grid-item {
    display: grid;
    gap: 0.65rem;
    min-height: 12rem;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 1.5rem;
    padding: 1.25rem;
    background:
      linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.92)),
      linear-gradient(
        130deg,
        rgba(56, 189, 248, 0.14),
        rgba(244, 114, 182, 0.08)
      );
    box-shadow: 0 18px 50px rgba(148, 163, 184, 0.18);
    transform: translateY(calc(var(--item-index) * 2px));
  }

  .feature-grid-item strong {
    font-size: 1rem;
    line-height: 1.1;
    color: rgb(15 23 42);
  }

  .feature-grid-item p {
    margin: 0;
    line-height: 1.6;
    color: rgb(71 85 105);
  }
</style>
